// Created by Zoltan Dul (https://github.com/ZoliQua) 2025-2026
//
// Bundled Arabic font for the PDF report (ar locale). A subset of Noto Naskh
// Arabic (OFL) — base Arabic block + Arabic Presentation Forms-A/-B +
// ASCII/Latin-1 + punctuation. jsPDF applies no OpenType shaping, so Arabic text
// must be pre-shaped to its contextual presentation forms and RTL-reordered
// before `doc.text` (see `shapeArabic` in ./arabicShaper) — this font carries
// the Presentation Forms glyphs that pre-shaping targets.
//
// Lazy-loaded (dynamic import) by the PDF export path, so it never enters the
// main bundle or a non-Arabic export. Regular + Bold; italic/bold-italic map to
// the upright faces (no synthesized slant).
import type { FontRegistrable } from "./roboto";

export const PDF_FONT_ARABIC = "NotoArabic";
const AR_REGULAR_B64 = "";
const AR_BOLD_B64 = "";
const registered = new WeakSet<object>();

export function registerArabicFont(doc: FontRegistrable): boolean {
  if (typeof doc.addFileToVFS !== "function" || typeof doc.addFont !== "function") return false;
  if (registered.has(doc as object)) return true;
  doc.addFileToVFS("NotoArabic-Regular.ttf", AR_REGULAR_B64);
  doc.addFileToVFS("NotoArabic-Bold.ttf", AR_BOLD_B64);
  doc.addFont("NotoArabic-Regular.ttf", PDF_FONT_ARABIC, "normal");
  doc.addFont("NotoArabic-Bold.ttf", PDF_FONT_ARABIC, "bold");
  doc.addFont("NotoArabic-Regular.ttf", PDF_FONT_ARABIC, "italic");
  doc.addFont("NotoArabic-Bold.ttf", PDF_FONT_ARABIC, "bolditalic");
  registered.add(doc as object);
  return true;
}
